package org.icu.sepsis.ai;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.junit.jupiter.api.Test;import org.icu.sepsis.application.Store;import org.icu.sepsis.application.QueryService;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.AuthorityUtils;
class AiNoteReviewSecurityTest {
 @Test void nurseCannotInvokeNoteReviewEvenByCallingTheSharedBriefEndpoint(){var ai=mock(AiAssistService.class);var store=mock(Store.class);var q=mock(QueryService.class);var controller=new AiController(ai,store,q);var request=new AiController.BriefRequest();request.kind="note_review";var actor=new UsernamePasswordAuthenticationToken("nurse","",AuthorityUtils.createAuthorityList("ROLE_NURSE"));assertThrows(org.icu.sepsis.api.ApiException.class,()->controller.brief("patient",request,actor));verifyNoInteractions(ai,store,q);}
 @Test void nurseCannotInvokeAutomaticDecision(){var ai=mock(AiAssistService.class);var store=mock(Store.class);var q=mock(QueryService.class);var c=new AiController(ai,store,q);var r=new AiController.BriefRequest();r.kind="decision";var actor=new UsernamePasswordAuthenticationToken("nurse","",AuthorityUtils.createAuthorityList("ROLE_NURSE"));assertThrows(org.icu.sepsis.api.ApiException.class,()->c.brief("patient",r,actor));verifyNoInteractions(ai,store,q);}
}
